// examples/physics/bodies-2d: Rapier rigid bodies in the 2D room, through the physics extension.
//
// Shows: @mcthaydt/automata-physics/2d inside base-2d's sim. The room's tiles are fixed bodies, an invisible
// kinematic box follows Wick, and crates and stones are dynamic bodies: Wick shoves them, they tumble down the
// ledges and pile up. Drop more and watch the collision events count up. Physics runs inside the sim
// (sim/bodies.plugin.ts), so the pile is the same on every engine (golden.parity.test.ts); this page only
// sends the drops and draws the bodies.
// Files: boot.ts types the boot failures for base-2d's bootPage; bodies-sim.ts makes the sim and places the bodies (walls from sim/room-colliders.ts); sim/ is what runs
// each step; layer.ts draws the bodies from the sim's RenderDelta with the 8 × 8 sprites in art/.
// Controls: arrows or A/D to move, Space, Z, W or Up to jump, B, X or C to drop a body above Wick; on-screen
// buttons on touch (▣ drops).
// Base: base-2d (`@af-examples/base-2d`: the room, Wick, input and the loop through `playRoom`).
// Packages: @mcthaydt/automata-physics (Rapier, deterministic build), @mcthaydt/automata-host, pixi.js, effect,
// and the base's own.
import '@af-examples/base-2d/no-eval'
import '@fontsource/pixelify-sans/latin-400.css'
import '@fontsource/pixelify-sans/latin-700.css'
import '@af-examples/base-2d/style.css'
import './bodies-panel.css'
import { bootPage, ROOM } from '@af-examples/base-2d'
import { playRoom } from '@af-examples/base-2d/play'
import { textureFromPixels } from '@af-examples/base-2d/render'
import { makeHosting } from '@mcthaydt/automata-host'
import type { Command, Sim } from '@mcthaydt/automata-sim'
import { Effect, Scope } from 'effect'
import { CRATE, STONE } from './art/sprites.ts'
import { createBodiesSim } from './bodies-sim.ts'
import { hostReady, playBodies } from './boot.ts'
import { bodiesLayer } from './layer.ts'
import { Drop } from './sim/bodies.plugin.ts'

/** Must equal `[game] id` in ship.config.ts; the host checks it. */
const GAME_ID = 'demo-physics-bodies-2d'

const found = document.querySelector<HTMLElement>('#game')
if (found === null) throw new Error('index.html has no #game element')
const root: HTMLElement = found

// Drops wait here until the next sim step sends them as commands (input never changes the sim directly).
let dropsWanted = 0
const DROP_KEYS = new Set(['KeyB', 'KeyX', 'KeyC'])
window.addEventListener('keydown', (event) => {
  if (DROP_KEYS.has(event.code) && !event.repeat) dropsWanted++
})

/**
 * At most one drop per step; any more wait for the next. The base's `move` takes `seq = tick` for player 0, so
 * a drop takes a number from the top half of the u32 range, where `move` will not reach for over a year of play.
 */
function dropCommands(sim: Sim): Command[] {
  if (dropsWanted === 0) return []
  dropsWanted--
  return [{ tick: sim.tick, source: 0, seq: 0x80000000 + sim.tick, type: Drop.id, payload: {} }]
}

const program = Effect.gen(function* () {
  yield* hostReady(
    Effect.gen(function* () {
      const hosting = yield* makeHosting({ gameId: GAME_ID, wants: [], pauseBehavior: 'pause' })
      yield* hosting.ready
    }),
  )
  // Nothing was drawn before this line: the page stays empty until the host says ready.
  let bumps = 0
  const counter = document.createElement('aside')
  counter.className = 'bodies-panel'
  const showBumps = () => {
    counter.textContent = `Collisions: ${bumps}`
    root.dataset.bumps = String(bumps)
  }
  const bodies = bodiesLayer(
    ROOM.rows.length * ROOM.tileSize,
    { crate: textureFromPixels(CRATE), stone: textureFromPixels(STONE) },
    (drawn) => {
      root.dataset.bodies = String(drawn.count)
      root.dataset.crateX = String(drawn.crateX)
    },
  )
  const play = yield* playBodies(() =>
    playRoom(root, {
      createSim: createBodiesSim,
      commands: dropCommands,
      onStep: (result) => {
        const started = result.events.filter((event) => event.type === 'physics2d.collision-started').length
        if (started > 0) {
          bumps += started
          showBumps()
        }
      },
      layers: [bodies],
    }),
  )
  // A touch button for drops, beside the base's move and jump buttons.
  const dropButton = document.createElement('button')
  dropButton.type = 'button'
  dropButton.className = 'drop'
  dropButton.textContent = '▣'
  dropButton.setAttribute('aria-label', 'Drop a body')
  dropButton.addEventListener('pointerdown', (event) => {
    event.preventDefault()
    dropsWanted++
  })
  root.querySelector('.touch .jump')?.before(dropButton)
  root.append(counter)
  showBumps()
  play.start()
})

// The host connection lives as long as the page, so its scope is never closed. bootPage sets data-state to
// ready, or shows base-2d's failure message ("This device can't run the game." when Rapier won't load).
const pageScope = Effect.runSync(Scope.make())
void bootPage({
  root,
  html: document.documentElement,
  start: program.pipe(Scope.extend(pageScope)),
  log: (message, error) => console.error(message, error),
})

/**
 * ui/primitives: every ui primitive at every reference size, with no renderer.
 *
 * What it shows:
 * - ScreenFrame with CornerControls, a ScrollList and an ActionBar.
 * - A Dialog, the LoaderOverlay, and the boot failure panel.
 * - The M4 primitives: Split, OptionGroup, PagerDots, PagedGrid, Button, IconButton, Toggle, Slider, Chip, Modal,
 *   Sheet and Toast.
 * - Each is laid out by the geometry owner from what the window and a (fake) Ruken host report:
 *   the safe area, Ruken's reserved strip, the keyboard and TV scale.
 *
 * Controls: pick a primitive and a variant at the top. Each card is that primitive in a frame of
 * one reference size, from 360x640 to 1024x1366 and the phone held sideways at 780x270. Inside a
 * card, Tab and the arrow keys move focus as a player's keyboard or controller would. Open a card
 * on its own (its link) to see it full-window, and resize the window to watch the owner re-measure.
 *
 * Base: none (renderer-free). Packages: `@mcthaydt/automata-ui`; `@mcthaydt/automata-testing` for
 * the reference sizes and Ruken's display-metrics fixture.
 */

import '@mcthaydt/automata-ui/theme.css'
import { hostDisplay, REFERENCE_SIZES, VARIANTS, type Variant } from '@mcthaydt/automata-testing'
import {
  classifyFormFactor,
  classifyHeightTier,
  createGeometryOwner,
  installGlobalErrorHandlers,
  suppressPageGestures,
  type ViewportWindow,
} from '@mcthaydt/automata-ui'
import { mount, unmount } from 'svelte'
import Frame from './src/Frame.svelte'
import Gallery from './src/Gallery.svelte'

export const PRIMITIVES = [
  'screen',
  'dialog',
  'loader',
  'error',
  'split',
  'options',
  'pager',
  'paged-grid',
  'controls',
  'chip',
  'modal',
  'sheet',
  'toast',
  'leaderboard',
] as const
export type Primitive = (typeof PRIMITIVES)[number]

const isPrimitive = (value: string | null): value is Primitive => PRIMITIVES.some((name) => name === value)

function variantNamed(name: string | null): Variant {
  return VARIANTS.find((variant) => variant.name === name) ?? (VARIANTS[0] as Variant)
}

/**
 * The real window, or the real window with a keyboard laid over its foot. A browser only opens the
 * keyboard for a focused text field, so the demo stands one in by shrinking the visual viewport the
 * owner reads, exactly as the keyboard would.
 */
function viewportFor(variant: Variant): { window: ViewportWindow; keyboard: () => number } {
  const keyboard = (): number =>
    variant.keyboard?.({
      name: 'window',
      width: window.innerWidth,
      height: window.innerHeight,
      formFactor: classifyFormFactor(window.innerWidth, window.innerHeight),
      heightTier: classifyHeightTier(window.innerHeight),
      group: 'boundary',
    }) ?? 0
  if (variant.keyboard === undefined) return { window, keyboard }
  const covered: ViewportWindow = {
    get innerWidth() {
      return window.innerWidth
    },
    get innerHeight() {
      return window.innerHeight
    },
    visualViewport: {
      get height() {
        return window.innerHeight - keyboard()
      },
      offsetTop: 0,
      addEventListener: (type, listener) => window.visualViewport?.addEventListener(type, listener),
      removeEventListener: (type, listener) => window.visualViewport?.removeEventListener(type, listener),
    },
    addEventListener: (type, listener) => window.addEventListener(type, listener),
    removeEventListener: (type, listener) => window.removeEventListener(type, listener),
  }
  return { window: covered, keyboard }
}

/** Fonts loaded and two frames drawn, so measured layout (the action bar's collapse) has settled. */
async function settled(): Promise<void> {
  await document.fonts.ready
  for (let frame = 0; frame < 2; frame += 1) {
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()))
  }
}

/** One primitive, full-window, laid out by a real geometry owner, as a game would boot it. */
async function startFrame(
  target: HTMLElement,
  primitive: Primitive,
  variant: Variant,
): Promise<() => Promise<void>> {
  const root = document.documentElement
  const strip = variant.hostReserved
  const host =
    strip === undefined && variant.scale === undefined
      ? undefined
      : hostDisplay({ edge: strip?.edge ?? 'right', width: strip?.width ?? 0, scale: variant.scale ?? 1 })
  const viewport = viewportFor(variant)
  const owner = createGeometryOwner({ window: viewport.window, root, host })
  // Browser hygiene a game installs at boot: no page menus over the game, and a last-resort report.
  const releaseGestures = suppressPageGestures(document)
  const releaseErrors = installGlobalErrorHandlers(window, (errorClass) =>
    console.error(`uncaught ${errorClass}`),
  )
  const app = mount(Frame, {
    target,
    props: { primitive, geometry: owner.geometry, strip, keyboard: viewport.keyboard },
  })
  await settled()
  root.dataset.ready = ''
  return async () => {
    await unmount(app)
    owner.dispose()
    releaseGestures()
    releaseErrors()
    delete root.dataset.ready
  }
}

/** The gallery: the chosen primitive and variant in a card per reference size. */
async function startGallery(
  target: HTMLElement,
  primitive: Primitive,
  variant: Variant,
  url: URL,
): Promise<() => Promise<void>> {
  const app = mount(Gallery, {
    target,
    props: {
      primitives: PRIMITIVES,
      sizes: REFERENCE_SIZES,
      variants: VARIANTS.map((each) => each.name),
      initialShow: primitive,
      initialVariant: variant.name,
      // Each card loads this same page in frame mode. Not `new URL('./index.html', import.meta.url)`: Vite
      // bundles that as an asset copy, whose `./main.ts` is a 404 in the build.
      page: `${url.origin}${url.pathname}`,
    },
  })
  await settled()
  return async () => {
    await unmount(app)
  }
}

/** Starts the demo in `target` from the page URL: `?frame=<primitive>` draws one, otherwise the gallery. */
export function start(target: HTMLElement, url: URL): Promise<() => Promise<void>> {
  const frame = url.searchParams.get('frame')
  const variant = variantNamed(url.searchParams.get('variant'))
  if (isPrimitive(frame)) return startFrame(target, frame, variant)
  const show = url.searchParams.get('show')
  return startGallery(target, isPrimitive(show) ? show : 'screen', variant, url)
}

const app = document.getElementById('app')
if (app !== null) void start(app, new URL(window.location.href))

// examples/content/hot-reload: content that changes while the game runs.
//
// Shows: the room as a content file (content/room.toml) compiled by automata-content, and edited live. Run
// `pnpm --filter @af-examples/content-hot-reload dev`, open the page, change a tile in content/room.toml and
// save: Wick's room is rebuilt in place, on a fresh sim, without reloading the page. Save a mistake (a row of
// the wrong width, a second P) and the compiler's message shows over the room, which stays as it last
// compiled; the next good save clears it. A production build embeds the content and its hash, and never
// reloads.
// Controls: arrows or A/D to move, Space, Z, W or Up to jump; on-screen buttons on touch.
// Base: base-2d (`@af-examples/base-2d`: the room, Wick, input and the loop through `playRoom`).
// Packages: @mcthaydt/automata-content (its Vite plugin and `virtual:automata/content`),
// @mcthaydt/automata-host, effect, and the base's own.
import '@af-examples/base-2d/no-eval'
import '@fontsource/pixelify-sans/latin-400.css'
import '@fontsource/pixelify-sans/latin-700.css'
import '@af-examples/base-2d/style.css'
import './content-panel.css'
import { content, contentHash } from 'virtual:automata/content'
import { type PlayRoom, playRoom } from '@af-examples/base-2d/play'
import { makeHosting } from '@mcthaydt/automata-host'
import { Effect } from 'effect'

/** Must equal `[game] id` in ship.config.ts; the host checks it. */
const GAME_ID = 'demo-content-hot-reload'

const found = document.querySelector<HTMLElement>('#game')
if (found === null) throw new Error('index.html has no #game element')
const root: HTMLElement = found

/** The compiler's messages for a bad save, over the room until the next good one. */
const problems = document.createElement('aside')
problems.className = 'content-problems'
problems.hidden = true

/** Shows which content is in play: the page's journeys read it, and so can you. */
function showContent(hash: string): void {
  root.dataset.contentHash = hash
  problems.hidden = true
  problems.replaceChildren()
}

function showProblems(
  lines: readonly string[],
  heading = "content/room.toml didn't compile. Still playing the last good room.",
): void {
  const title = document.createElement('h2')
  title.textContent = heading
  const list = document.createElement('pre')
  list.textContent = lines.join('\n')
  problems.replaceChildren(title, list)
  problems.hidden = false
  root.dataset.contentProblems = String(lines.length)
}

/**
 * In dev, follows content/ as it is saved. The plugin recompiles on each save and sends `automata:content`
 * once the new content is ready, or `automata:content-error` with the compiler's messages. The browser has
 * already loaded `virtual:automata/content` once, so reading it again takes a new URL: the hash makes one.
 */
function followSaves(play: PlayRoom): void {
  const hot = import.meta.hot
  if (hot === undefined) return
  // Two quick saves start two imports, and the older one can finish last: only the newest save's room plays.
  let newest = ''
  hot.on('automata:content', async ({ hash }: { hash: string }) => {
    newest = hash
    const url = `/@id/__x00__virtual:automata/content?v=${hash}`
    try {
      const fresh: typeof import('virtual:automata/content') = await import(/* @vite-ignore */ url)
      if (hash !== newest) return
      // A new room is a new world: the sim and the renderer start over in it.
      await play.restart(fresh.content.room)
      if (hash === newest) showContent(fresh.contentHash)
    } catch (error) {
      // The compiler checked the room, so this is the page failing (a lost dev server, a renderer that could not
      // start): the last good room plays on, and the panel says what went wrong.
      showProblems(
        [error instanceof Error ? error.message : String(error)],
        "The new room couldn't start. Still playing the last good room.",
      )
    }
  })
  hot.on('automata:content-error', ({ diagnostics }: { diagnostics: readonly string[] }) =>
    showProblems(diagnostics),
  )
}

const program = Effect.gen(function* () {
  const hosting = yield* makeHosting({ gameId: GAME_ID, wants: [], pauseBehavior: 'pause' })
  yield* hosting.ready
  // Nothing was drawn before this line: the page stays empty until the host says ready.
  const play = yield* Effect.promise(() => playRoom(root, { room: content.room }))
  root.append(problems)
  showContent(contentHash)
  followSaves(play)
  play.start()
  document.documentElement.dataset.state = 'ready'
  yield* Effect.never
})

Effect.runPromise(Effect.scoped(program)).catch((error: unknown) => {
  root.textContent = "Couldn't connect to Ruken."
  document.documentElement.dataset.state = 'failed'
  console.error(error)
})

// games/emberwick: AF's 2D base project, a character in a room.
//
// Shows: a complete small game on `startGame`. A pixel-art character runs and jumps through one single-screen
// room to an ember (Wick, a hooded lantern-bearer in mossy ruins at night, Endesga 64, lit by pixel lights),
// through splash → menu → room → pause → end. The runtime completes the Ruken handshake and draws nothing
// before the host says ready; opened directly, it runs standalone.
// Controls: arrows or A/D to move, Space, Z, W or Up to jump, Escape or P to pause; on-screen buttons on touch.
// Base: this is the 2D base. Demos build on it through `@af-examples/base-2d`.
// Packages: @mcthaydt/automata-game (runtime, render-pixi, host, ui), @mcthaydt/automata-sim, pixi.js,
// @fontsource/pixelify-sans (OFL font); @mcthaydt/automata-ship for packaging.
import '@mcthaydt/automata-game/no-eval'
import '@fontsource/pixelify-sans/latin-400.css'
import '@fontsource/pixelify-sans/latin-700.css'
import { startGame } from '@mcthaydt/automata-game'
import { emberwick } from './src/game.ts'

startGame(emberwick)
